/*
 * prog22_snake_camel_convert
 *
 * Re‑implementation of the original program based on reverse‑engineering.
 *
 * Usage:
 *   prog22_snake_camel_convert to_camel   <snake_string>
 *   prog22_snake_camel_convert to_snake   <camelString>
 *
 * If the number of arguments is wrong the program prints:
 *   USAGE
 *
 * If the mode is not one of the two supported strings it prints:
 *   INVALID_MODE
 *
 * The conversion follows the logic that was observed in the binary:
 *
 *   to_camel :  snake_case  →  lowerCamelCase
 *               – underscores are removed
 *               – the character following an underscore is upper‑cased
 *               – the first character is left unchanged
 *
 *   to_snake :  lowerCamelCase  →  snake_case
 *               – an underscore is inserted before each upper‑case letter
 *               – the upper‑case letter is converted to lower case
 *               – the first character is never preceded by an underscore
 *
 * The output is written into a static buffer of size 1024 (the same size
 * used by the original binary).  If the result would be longer, it is
 * silently truncated to fit the buffer.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024

static char out_buf[OUT_BUF_SIZE];

/* Convert a snake_case string to lowerCamelCase */
static void to_camel(const char *src)
{
    size_t out_idx = 0;
    int capitalize_next = 0;          /* set after an underscore */

    for (size_t i = 0; src[i] != '\0' && out_idx + 1 < OUT_BUF_SIZE; ++i) {
        char ch = src[i];

        if (ch == '_') {
            capitalize_next = 1;      /* next character will be upper‑cased */
            continue;                 /* underscore itself is omitted */
        }

        if (capitalize_next) {
            ch = (char)toupper((unsigned char)ch);
            capitalize_next = 0;
        }

        out_buf[out_idx++] = ch;
    }
    out_buf[out_idx] = '\0';
}

/* Convert a lowerCamelCase string to snake_case */
static void to_snake(const char *src)
{
    size_t out_idx = 0;

    for (size_t i = 0; src[i] != '\0' && out_idx + 1 < OUT_BUF_SIZE; ++i) {
        char ch = src[i];

        if (isupper((unsigned char)ch)) {
            /* Insert '_' before the lower‑cased character, unless it is the
               very first character (the original binary never added a leading
               underscore). */
            if (i != 0 && out_idx + 1 < OUT_BUF_SIZE) {
                out_buf[out_idx++] = '_';
            }
            ch = (char)tolower((unsigned char)ch);
        }

        out_buf[out_idx++] = ch;
    }
    out_buf[out_idx] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
        puts(out_buf);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
        puts(out_buf);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
